class Vehicle {
  readonly wheels: number;
  constructor(wheels: number) {
    this.wheels = wheels;
  }
  describe(): string {
    return `${this.wheels} wheels`;
  }
}

class Bike extends Vehicle {
  constructor() {
    super(2);          // must come before any use of `this`
  }
}

console.log(new Bike().describe());   // inherited, not redefined: "2 wheels"

class Base {
  protected readonly token: string;
  private readonly secret = "hidden";
  constructor(token: string) {
    this.token = token;
  }
  reveal(): string {
    return this.secret;    // fine - inside the class
  }
}

class Child extends Base {
  show(): string {
    return this.token;     // fine - protected, and Child extends Base
    // return this.secret; // error: private, invisible even to a subclass
  }
}

console.log(new Child("abc123").show());
console.log(new Base("xyz").reveal());

import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template literal.

await writeProjectFile("week5/generated/day3-inline.spec.ts", `// Week 5, Day 3 — the "before". Three tests, no page objects.
//
// Nothing here is wrong. It passes. Read it and count instead:
//   "Enter Email"    appears 3 times
//   "Enter Password" appears 3 times
//   "Login" button   appears 3 times
//   "**/dashboard"   appears 3 times
// Twelve places to edit when the login form is redesigned, in one file of three
// tests. A real suite has three hundred tests.
//
// Written by a cell in week5/day3_2.ipynb. Run it yourself:
//   npx playwright test week5/generated/day3-inline.spec.ts
import { test, expect } from "@playwright/test";

test.describe("Inline locators", () => {
  test("Step 1 — sign in and see the balance", async ({ page }) => {
    await page.goto("/");
    await page.getByPlaceholder("Enter Email").fill("leela@gmail.com");
    await page.getByPlaceholder("Enter Password").fill("Leela@123");
    await page.getByRole("button", { name: "Login" }).click();
    await page.waitForURL("**/dashboard");
    await expect(page.getByText("Account Balance", { exact: true })).toBeVisible();
  });

  test("Step 2 — sign in and open a tile", async ({ page }) => {
    await page.goto("/");
    await page.getByPlaceholder("Enter Email").fill("leela@gmail.com");
    await page.getByPlaceholder("Enter Password").fill("Leela@123");
    await page.getByRole("button", { name: "Login" }).click();
    await page.waitForURL("**/dashboard");
    await page.getByText("Pay Bills", { exact: true }).click();
    await expect(page).toHaveURL(/paymentDashboard/);
  });

  test("Step 3 — sign in and sign out", async ({ page }) => {
    await page.goto("/");
    await page.getByPlaceholder("Enter Email").fill("leela@gmail.com");
    await page.getByPlaceholder("Enter Password").fill("Leela@123");
    await page.getByRole("button", { name: "Login" }).click();
    await page.waitForURL("**/dashboard");
    await page.getByRole("button", { name: "LogOut" }).click();
    await expect(page).toHaveURL(/login/);
  });
});
`);

// Expected: 3 passed. Working code - the problem is not correctness.
await runSpec("week5/generated/day3-inline.spec.ts");

import { writeProjectFile } from "../_shared/deno-helpers.ts";

// No test() calls, so the runner never collects it - just a class.

// Backslashes before ` and ${ because each file sits inside a template literal.

await writeProjectFile("week5/generated/pages/BasePage.ts", `// Week 5, Days 3-4 — what every page class shares.
//
// A base class exists for the plumbing every page needs and nothing else. Resist
// putting business logic here: the moment BasePage knows about payees, it is not a
// base class any more.
import { type Page } from "@playwright/test";

export abstract class BasePage {
  // \`protected\` so subclasses can use it and tests cannot reach past the class.
  protected readonly page: Page;

  constructor(page: Page) {
    this.page = page;
  }

  /** Navigate to a path relative to the config's baseURL. */
  async goto(path = "/"): Promise<void> {
    await this.page.goto(path);
  }

  /** The last segment of the URL — useful for asserting which screen we are on. */
  section(): string {
    return this.page.url().split("/").pop() ?? "";
  }
}
`);

import { writeProjectFile } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template literal.

await writeProjectFile("week5/generated/pages/LoginPage.ts", `// Week 5, Days 3-4 — the login screen.
//
// One class per page. Locators built once in the constructor; methods named for
// what a user does. No expect() anywhere — the test decides what should be true.
import { type Locator, type Page } from "@playwright/test";
import { USERS, type BankUser } from "../../../_shared/test-helpers";
import { BasePage } from "./BasePage";

export class LoginPage extends BasePage {
  readonly emailBox: Locator;
  readonly passwordBox: Locator;
  readonly loginButton: Locator;

  constructor(page: Page) {
    super(page);
    this.emailBox = page.getByPlaceholder("Enter Email");
    this.passwordBox = page.getByPlaceholder("Enter Password");
    this.loginButton = page.getByRole("button", { name: "Login" });
  }

  async signIn(user: BankUser = USERS[0]): Promise<void> {
    await this.emailBox.fill(user.email);
    await this.passwordBox.fill(user.password);
    await this.loginButton.click();
    await this.page.waitForURL("**/dashboard");
  }

  /**
   * Does NOT wait for a dashboard, because a refused login never reaches one.
   * Kept separate from signIn() so neither method has to guess the outcome — the
   * same reason page objects do not assert.
   */
  async signInExpectingRefusal(email: string, password: string): Promise<void> {
    if (email) await this.emailBox.fill(email);
    if (password) await this.passwordBox.fill(password);
    await this.loginButton.click();
  }
}
`);

await writeProjectFile("week5/generated/pages/DashboardPage.ts", `// Week 5, Days 3-4 — the dashboard.
//
// The tiles are <p class="card-text"> elements, not links — getByRole("link") finds
// nothing on this page. A real quirk, and exactly the kind of detail a page object
// should absorb so no test has to know it.
import { type Locator, type Page } from "@playwright/test";
import { BasePage } from "./BasePage";

export class DashboardPage extends BasePage {
  readonly userName: Locator;
  readonly logoutButton: Locator;
  readonly accountBalance: Locator;
  readonly tiles: Locator;

  constructor(page: Page) {
    super(page);
    this.userName = page.getByText("Leela");
    this.logoutButton = page.getByRole("button", { name: "LogOut" });
    this.accountBalance = page.getByText("Account Balance", { exact: true });
    this.tiles = page.locator("p.card-text");
  }

  /** Opens a dashboard tile by its visible label. */
  async openTile(label: string): Promise<void> {
    await this.page.getByText(label, { exact: true }).click();
  }

  async signOut(): Promise<void> {
    await this.logoutButton.click();
    await this.page.waitForURL("**/login");
  }
}
`);

import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template literal.

await writeProjectFile("week5/generated/day3-pom.spec.ts", `// Week 5, Day 3 — the "after". The same three journeys, through page classes.
//
// The Page Object Model, stated as three rules:
//   1. One class per page (or per meaningful region of one).
//   2. Locators are fields; actions are methods named for what a person does.
//   3. No expect() inside the class. The class supplies facts; the test judges them.
//
// Rule 3 is the one people break first, and it is the one that pays. Because
// LoginPage.signIn() asserts nothing, Step 4 below can reuse the very same class
// to check that a BAD password is refused. A class with an assertion baked in
// could only ever test the happy path.
//
// Written by a cell in week5/day3_2.ipynb. Run it yourself:
//   npx playwright test week5/generated/day3-pom.spec.ts
import { test, expect } from "@playwright/test";
import { LoginPage } from "./pages/LoginPage";
import { DashboardPage } from "./pages/DashboardPage";

test.describe("Page Object Model — the pattern", () => {
  test("Step 1 — sign in and see the balance", async ({ page }) => {
    const loginPage = new LoginPage(page);
    const dashboardPage = new DashboardPage(page);

    await loginPage.goto("/");
    await loginPage.signIn();

    await expect(dashboardPage.accountBalance).toBeVisible();
  });

  test("Step 2 — sign in and open a tile", async ({ page }) => {
    const loginPage = new LoginPage(page);
    const dashboardPage = new DashboardPage(page);

    await loginPage.goto("/");
    await loginPage.signIn();
    await dashboardPage.openTile("Pay Bills");

    await expect(page).toHaveURL(/paymentDashboard/);
  });

  test("Step 3 — sign in and sign out", async ({ page }) => {
    const loginPage = new LoginPage(page);
    const dashboardPage = new DashboardPage(page);

    await loginPage.goto("/");
    await loginPage.signIn();
    await dashboardPage.signOut();

    await expect(page).toHaveURL(/login/);
  });

  test("Step 4 — the same class, the opposite outcome", async ({ page }) => {
    const loginPage = new LoginPage(page);

    await loginPage.goto("/");
    // signInExpectingRefusal, not signIn — because signIn() waits for a dashboard
    // that a refused login never reaches. Two methods, one for each outcome, so
    // neither has to guess. That is rule 3 in practice.
    await loginPage.signInExpectingRefusal("leela@gmail.com", "WrongPassword1");

    await expect(page).not.toHaveURL(/dashboard/);
  });

  test("Step 5 — what the base class gives every page", async ({ page }) => {
    const loginPage = new LoginPage(page);
    const dashboardPage = new DashboardPage(page);

    // goto() and section() live on BasePage. Neither LoginPage nor DashboardPage
    // defines them; both inherit them. BasePage is \`abstract\` — try
    // \`new BasePage(page)\` and TypeScript refuses. It is plumbing, not a page.
    await loginPage.goto("/");
    await loginPage.signIn();
    expect(dashboardPage.section()).toBe("dashboard");
  });
});
`);

// Expected: 5 passed.
await runSpec("week5/generated/day3-pom.spec.ts");

## Components, not just pages

A header, a nav bar, a data table appear on many pages. Making each a class and *composing* it
beats copying its locators into every page:

```ts
export class Header {
  readonly logoutButton: Locator;
  constructor(private readonly page: Page) {
    this.logoutButton = page.getByRole("button", { name: "LogOut" });
  }
  async signOut(): Promise<void> { await this.logoutButton.click(); }
}

export class DashboardPage extends BasePage {
  readonly header: Header;
  constructor(page: Page) {
    super(page);
    this.header = new Header(page);     // composition
  }
}
```

Now `dashboardPage.header.signOut()`. Change the logout button once, in `Header.ts`.

> `constructor(private readonly page: Page)` is shorthand: TypeScript declares the field *and*
> assigns it. Same as declaring `private readonly page` and writing `this.page = page`.

// Inheritance and composition side by side, with the browser stripped out so the
// dispatch is the only thing left to look at.
class PageBase {
  constructor(protected readonly name: string) {}
  section(): string {
    return this.name;
  }
}

class SiteHeader {
  signOut(): string {
    return "clicked LogOut";
  }
}

class Dashboard extends PageBase {
  readonly header = new SiteHeader();   // has-a: composition
  constructor() {
    super("dashboard");                 // is-a: inheritance
  }
}

const dash = new Dashboard();
console.log("inherited from PageBase :", dash.section());
console.log("composed from SiteHeader:", dash.header.signOut());
console.log("is it a PageBase?        ", dash instanceof PageBase);

## Returning the next page

Some teams have a method return the page it navigated to:

```ts
async signIn(user: BankUser): Promise<DashboardPage> {
  await this.loginButton.click();
  await this.page.waitForURL("**/dashboard");
  return new DashboardPage(this.page);
}
```

The test then reads `const dashboard = await loginPage.signIn(user)`.

| | Returning the next page | Fixtures ([day4_2](/learn/w5/d4/p2)) |
|---|---|---|
| Reads like a journey | **yes** | less so |
| Circular imports between page files | **a real risk** | no |
| Works when a click has two outcomes | no - which page do you return? | yes |

Pick one per repo and stick to it. Mixing both is what makes a suite hard to read.
